const PROFILS=[["Il meurt toujours en premier",{premiereMort:.35}],["Il garde son utilitaire en poche",{gaspilleUtilitaire:.8,mortPlusTard:.7}],["Il meurt seul, jamais \xE9chang\xE9",{echange:0,premiereMort:.03}],["Il vise le corps",{tete:.06}],["Son viseur est trop bas",{jambes:.35}],["Il fait peu de d\xE9g\xE2ts",{degats:60}],["Il a fait une grosse partie",{premiereMort:.04,gaspilleUtilitaire:.05,tete:.3,degats:175,premierSang:.25}]],choixAgent=document.getElementById("agent");for(const e of Agents.AGENTS)choixAgent.add(new Option(e.nom,e.code+"_PC_C",e.nom==="Skye",e.nom==="Skye"));const boutons=document.getElementById("boutons");for(const[e,o]of PROFILS){const t=document.createElement("button");t.textContent=e,t.onclick=()=>{const n=Simulation.rejouer(new Collecteur,Simulation.genererPartie(Date.now(),{...o,agent:choixAgent.value}));Stockage.enregistrer(Analyse.analyser(n,Stockage.objectif())),location.href="coach.html"},boutons.appendChild(t)}
